    return el.innerText.trim();
  }).filter(t => t.length > 0 && (t.includes('Unlimited') || t.includes('15 GB')));

  return {
    lines: linesEl ? linesEl.innerText : null,
    autoPayChecked: checkbox ? checkbox.checked : null,
    panelText: panel ? panel.innerText : null
  };
});

